#include "common.h"
#include "callees.h"
#include "include_asm.h"
#include "asm_functions/shared_levels.h"
#include "asm_functions/executable.h"

/* Builds a matrix that rolls by roll around the direction dir and writes it to out. */
void build_axis_roll_matrix(void *out, void *dir, float roll) {
    float M[4][4];
    float Rz[4][4];
    float Ry[4][4];
    float Rx[4][4];
    float ang[4];
    float d[4];
    float a;
    qcopy(d, dir);
    set_identity_matrix(M);
    a = -fast_atan2(d[0], d[1]);
    ang[0] = 0.0f;
    ang[1] = 0.0f;
    ang[2] = a;
    euler_to_matrix(Rz, ang);
    transform_vector(d, d, Rz);
    a = -fast_atan2(d[2], d[0]);
    ang[0] = 0.0f;
    ang[2] = 0.0f;
    ang[1] = a;
    fast_euler_to_matrix(Ry, ang);
    transform_vector(d, d, Ry);
    ang[2] = roll;
    ang[0] = 0.0f;
    ang[1] = 0.0f;
    fast_euler_to_matrix(Rx, ang);
    multiply_matrix(M, Rz, M);
    multiply_matrix(M, Ry, M);
    multiply_matrix(M, Rx, M);
    matrix_from_basis_rows(Ry, Ry);
    multiply_matrix(M, Ry, M);
    matrix_from_basis_rows(Rz, Rz);
    multiply_matrix(M, Rz, M);
    qcopy(d, dir);
    transform_vector(d, d, M);
    copy_matrix3x4(out, M);
}
